        ['Recipes', 'Heart-Healthy Dinners for Busy Weeknights', 'Balanced meals with flavor, fiber, and minimal prep.', imageMap.recipes]
      ],
      'Skin Care': [
        ['Skin Care', "Beginner's Guide to Sensitive Skin", 'How to build a simple routine that supports your barrier.', imageMap.skin],
        ['Skin Care', 'Eczema Solutions: Knowledge for Self-Care', 'Expert tips for managing triggers and flares.', imageMap.products],
        ['Skin Care', 'What Dermatologists Want You to Know About Sunscreen', 'Daily protection explained without the confusion.', imageMap.skin]
      ]
    };

    const articleGrid = document.getElementById('articleGrid');
    const tabButtons = document.querySelectorAll('.tab-button');

    function renderArticles(category) {
      articleGrid.innerHTML = articles[category].map((article, index) => `
        <article class="article-card" style="animation-delay:${index * 35}ms">
          <img src="${article[3]}" alt="${article[1]}">
          <div class="article-body">
            <small>${article[0]}</small>
            <h3>${article[1]}</h3>
            <p>${article[2]}</p>
            <a href="#">Read article →</a>
          </div>
        </article>
      `).join('');
    }

    tabButtons.forEach((button) => {
      button.addEventListener('click', () => {
        tabButtons.forEach((tab) => {
          tab.classList.remove('active');
          tab.setAttribute('aria-selected', 'false');
        });
        button.classList.add('active');
        button.setAttribute('aria-selected', 'true');
        renderArticles(button.dataset.tab);
      });
    });

    renderArticles('Top Reads');

    document.getElementById('signupForm').addEventListener('submit', (event) => {
      event.preventDefault();
      const email = document.getElementById('emailInput').value.trim();
      const message = document.getElementById('signupMessage');
      if (email) {
        message.textContent = 'Thanks — you are on the list.';
        event.currentTarget.reset();
      }
    });
  </script>
</body>
</html>
